<?php
require_once __DIR__.'/../includes/authorization.php';require_role('admin');require_once __DIR__.'/../includes/Repositories/ProductRepository.php';$repo=new ProductRepository();$errors=[];
if(is_post()){if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('admin-products'));}$id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';if(!$id){$errors[]='Produk tidak valid.';}elseif($action==='archive'){$repo->archiveAdmin((int)$id);flash('success','Produk diarsipkan oleh admin.');redirect(page_url('admin-products'));}elseif($action==='restore'){$repo->restoreAdmin((int)$id);flash('success','Produk diaktifkan kembali.');redirect(page_url('admin-products'));}}
$products=$repo->adminAll();$pageTitle='Kelola Produk';require __DIR__.'/../includes/header.php';
?><section class="section-padding page-section"><div class="container"><div class="page-toolbar d-flex justify-content-between align-items-center gap-2 flex-wrap"><?=back_link('admin-dashboard','Kembali ke dashboard admin')?><a class="btn btn-primary btn-sm" href="<?=e(page_url('admin-product-form'))?>"><i class="bi bi-plus-lg me-1"></i>Tambah produk</a></div><div class="section-heading mb-4"><span class="eyebrow">Admin</span><h2>Kelola <em>produk.</em></h2><p class="text-muted">Edit atau arsipkan produk tanpa merusak histori transaksi.</p></div><?php if($errors):?><div class="alert alert-danger"><?=implode('<br>',array_map('e',$errors))?></div><?php endif;?><div class="glass-card p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th>Seller</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=e($p['name'])?></strong><div class="small text-muted"><?=e($p['category'])?> · <?=e($p['city'])?></div></td><td><?=e($p['seller_name'])?></td><td><?=format_price((int)$p['price'])?></td><td><?=intval($p['stock'])?></td><td><?=e($p['status'])?></td><td><div class="d-flex gap-2"><a class="btn btn-soft btn-sm" href="<?=e(page_url('admin-product-edit',['id'=>$p['id']]))?>">Edit</a><?php if($p['status']==='archived'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="product_id" value="<?=intval($p['id'])?>"><button class="btn btn-primary btn-sm">Aktifkan</button></form><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="product_id" value="<?=intval($p['id'])?>"><button class="btn btn-outline-danger btn-sm">Hapus / Arsipkan</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>